-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
-- hl.on("hyprland.start", function ()
--   hl.exec_cmd(terminal)
--   hl.exec_cmd("nm-applet")
--   hl.exec_cmd("waybar & hyprpaper & firefox")
-- end)

hl.on("hyprland.start", function ()
  -- waybar via un lanceur qui le relance s'il crashe au boot (course avec le
  -- compositeur pas encore prêt pour le layer-shell → barre absente sinon).
  hl.exec_cmd("waybar-launch")
  -- Fond d'écran par workspace : démarre swww et écoute les bascules de
  -- workspace pour changer l'image (script ~/.local/bin/wallpaper-daemon,
  -- images dans ~/.config/wallpapers/).
  hl.exec_cmd("wallpaper-daemon")
  -- Rafraîchit la surbrillance des boutons de workspace de waybar à chaque
  -- changement (envoie SIGRTMIN+1 ; modules custom/wsN avec "signal":1).
  hl.exec_cmd("waybar-ws-refresh")
  -- Verrouille la session avant la mise en veille, pour que rabattre le
  -- couvercle mène à hyprlock et non au bureau (voir hypridle.conf ; aucun
  -- verrouillage sur inactivité n'est configuré).
  hl.exec_cmd("hypridle")
end)


