---- ENVIRONMENT VARIABLES ----
-------------------------------

-- See https://wiki.hypr.land/Configuring/Advanced-and-Cool/Environment-variables/

hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_SIZE", "24")

-- Ajoute ~/.local/bin au PATH des programmes lancés par Hyprland (binds,
-- boutons waybar…). Sinon les scripts perso (rofi-launcher, keybind-hint,
-- screenshot, wlogout-launch, system-update) ne sont pas trouvés, car les
-- exec de Hyprland utilisent un `sh -c` non-interactif qui ne lit pas le
-- PATH exporté dans .bashrc.
-- Idempotent : on ne préfixe que si absent (sinon chaque `hyprctl reload`
-- ré-ajoute une occurrence, car os.getenv relit le PATH déjà modifié).
local local_bin = os.getenv("HOME") .. "/.local/bin"
local cur_path = os.getenv("PATH") or ""
if not string.find(cur_path, local_bin, 1, true) then
    hl.env("PATH", local_bin .. ":" .. cur_path)
end


